css:
@custom-variant dark (&:where(.dark, .dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

:root {
  --cn-unit: .0625rem;
  --radius: calc(6 * var(--cn-unit));
  --cn-radius-control: max(0px, var(--radius));
  --cn-radius-item: max(0px, calc(var(--cn-radius-control) - 2 * var(--cn-unit)));
  --cn-radius-card: max(0px, calc(var(--cn-radius-control) + 4 * var(--cn-unit)));
  --cn-radius-frame: max(0px, calc(var(--cn-radius-control) + 6 * var(--cn-unit)));
  --cn-duration-fast: 100ms;
  --cn-duration-popup: 160ms;
  --cn-duration-spatial: 220ms;
  --cn-ease-standard: cubic-bezier(.2,0,0,1);
  --cn-ease-enter: cubic-bezier(.16,1,.3,1);
  --cn-ease-exit: cubic-bezier(.4,0,1,1);
  --cn-surface-page: var(--background);
  --cn-surface: var(--card);
  --cn-surface-popup: var(--popover);
  --cn-surface-muted: var(--muted);
  --cn-surface-hover: var(--accent);
  --cn-text: var(--foreground);
  --cn-text-muted: var(--muted-foreground);
  --cn-primary: var(--primary);
  --cn-primary-foreground: var(--primary-foreground);
  --cn-border: var(--border);
  --cn-border-control: var(--input);
  --cn-focus-color: var(--ring);
  --cn-status-destructive-foreground: var(--destructive-foreground);
  --cn-status-success-foreground: var(--success-foreground);
  --cn-status-warning-foreground: var(--warning-foreground);
  --cn-status-info-foreground: var(--info-foreground);
  --background: #f8f9fb;
  --foreground: #20242c;
  --card: #ffffff;
  --card-foreground: #20242c;
  --popover: #ffffff;
  --popover-foreground: #20242c;
  --primary: #25272c;
  --primary-foreground: #ffffff;
  --secondary: #f0f2f6;
  --secondary-foreground: #20242c;
  --muted: #f0f2f6;
  --muted-foreground: #5e6674;
  --accent: #e9edf4;
  --accent-foreground: #20242c;
  --border: #d5d9e1;
  --input: #7d8797;
  --ring: #4668d7;
  --cn-surface-raised: #ffffff;
  --cn-surface-pressed: #dfe5ef;
  --cn-surface-selected: #e8edf9;
  --cn-primary-hover: #353942;
  --cn-primary-pressed: #17191e;
  --cn-border-subtle: #e4e7ed;
  --cn-border-hover: #667184;
  --cn-border-active: #454f60;
  --cn-text-disabled: #7d8592;
  --cn-surface-disabled: #f0f2f6;
  --cn-border-disabled: #d5d9e1;
  --destructive: #b02a3b;
  --destructive-foreground: #ffffff;
  --cn-status-destructive-text: var(--destructive);
  --cn-status-destructive-border: var(--destructive);
  --cn-status-destructive-surface: #fff0f1;
  --success: #22673f;
  --success-foreground: #ffffff;
  --cn-status-success-text: var(--success);
  --cn-status-success-border: var(--success);
  --cn-status-success-surface: #edf7f0;
  --warning: #875300;
  --warning-foreground: #ffffff;
  --cn-status-warning-text: var(--warning);
  --cn-status-warning-border: var(--warning);
  --cn-status-warning-surface: #fff5df;
  --info: #2457b2;
  --info-foreground: #ffffff;
  --cn-status-info-text: var(--info);
  --cn-status-info-border: var(--info);
  --cn-status-info-surface: #edf3ff;
  --cn-shadow-control: none;
  --cn-shadow-card: 0 1px 2px rgb(17 24 39 / .04);
  --cn-shadow-popup: 0 4px 12px rgb(17 24 39 / .08), 0 1px 3px rgb(17 24 39 / .06);
  --cn-shadow-modal: 0 12px 32px rgb(17 24 39 / .12), 0 2px 6px rgb(17 24 39 / .06);
}

.dark {
  --cn-surface-page: var(--background);
  --cn-surface: var(--card);
  --cn-surface-popup: var(--popover);
  --cn-surface-muted: var(--muted);
  --cn-surface-hover: var(--accent);
  --cn-text: var(--foreground);
  --cn-text-muted: var(--muted-foreground);
  --cn-primary: var(--primary);
  --cn-primary-foreground: var(--primary-foreground);
  --cn-border: var(--border);
  --cn-border-control: var(--input);
  --cn-focus-color: var(--ring);
  --cn-status-destructive-foreground: var(--destructive-foreground);
  --cn-status-success-foreground: var(--success-foreground);
  --cn-status-warning-foreground: var(--warning-foreground);
  --cn-status-info-foreground: var(--info-foreground);
  --background: #111318;
  --foreground: #eef0f5;
  --card: #191c23;
  --card-foreground: #eef0f5;
  --popover: #252a34;
  --popover-foreground: #eef0f5;
  --primary: #e6e8ee;
  --primary-foreground: #191c23;
  --secondary: #20242c;
  --secondary-foreground: #eef0f5;
  --muted: #20242c;
  --muted-foreground: #a9b1c0;
  --accent: #303744;
  --accent-foreground: #eef0f5;
  --border: #414957;
  --input: #788497;
  --ring: #9bb4ff;
  --cn-surface-raised: #21252e;
  --cn-surface-pressed: #3a4353;
  --cn-surface-selected: #303d5c;
  --cn-primary-hover: #ffffff;
  --cn-primary-pressed: #cbd0db;
  --cn-border-subtle: #2c323e;
  --cn-border-hover: #9aa7bd;
  --cn-border-active: #bbc6d9;
  --cn-text-disabled: #77808f;
  --cn-surface-disabled: #20242c;
  --cn-border-disabled: #363d49;
  --destructive: #ff9da8;
  --destructive-foreground: #271217;
  --cn-status-destructive-text: var(--destructive);
  --cn-status-destructive-border: var(--destructive);
  --cn-status-destructive-surface: #39212a;
  --success: #92ddb0;
  --success-foreground: #12251a;
  --cn-status-success-text: var(--success);
  --cn-status-success-border: var(--success);
  --cn-status-success-surface: #1b3227;
  --warning: #f4c876;
  --warning-foreground: #281d0c;
  --cn-status-warning-text: var(--warning);
  --cn-status-warning-border: var(--warning);
  --cn-status-warning-surface: #382e1c;
  --info: #a4c4ff;
  --info-foreground: #13213b;
  --cn-status-info-text: var(--info);
  --cn-status-info-border: var(--info);
  --cn-status-info-surface: #20314e;
  --cn-shadow-control: none;
  --cn-shadow-card: none;
  --cn-shadow-popup: 0 6px 18px rgb(0 0 0 / .20);
  --cn-shadow-modal: 0 16px 40px rgb(0 0 0 / .28);
}

/* baseui-cn foundation v2 */
@layer base {
  :root { color-scheme: light; }
  .dark { color-scheme: dark; }
}
@keyframes cn-spin { to { transform: rotate(360deg); } }
@utility cn-loading { animation: cn-spin 1s linear infinite; }
@media (prefers-reduced-motion: reduce) {
  .cn-loading { animation: none; }
}
